#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "reference_owned_dmx_projection.h"
#include "owned_session_ik_pass.h"
#include <set>
#include <iostream>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=3)throw std::runtime_error("input output required");auto original=loadGraph(argv[1]);RecoveredOwnedDmxReferenceProjectionCandidate<Graph>p(original,[](const std::string&,auto&)->uint32_t{throw std::runtime_error("external resolver required");});auto expected=original;GraphTransformHierarchy h(expected);size_t expectedExecutions=0;SessionAttributeChanges expectedChanges;
 for(uint32_t i=0;i<expected.elements.size();++i)if(expected.strings.at(expected.elements[i].type)=="DmeRigIKConstraintOperator")if(executeSessionIkCandidate(expected,h,i,{0,0,0},{nullptr,nullptr,nullptr},&expectedChanges))++expectedExecutions;
 auto result=executeOwnedSessionIkPassCandidate(p,[](uint32_t){return std::array<uint32_t,3>{0xffffffffu,0xffffffffu,0xffffffffu};});if(result.executed!=expectedExecutions||result.changes.attributes!=expectedChanges.attributes)throw std::runtime_error("IK adapter mismatch");auto exported=p.exportReferences([](uint32_t,const auto&)->std::string{throw std::runtime_error("external export");});saveGraph(exported,argv[2]);auto loaded=loadGraph(argv[2]);validateGraph(loaded);std::set<std::pair<uint32_t,std::string>>changed(result.changes.attributes.begin(),result.changes.attributes.end());size_t changedValues=0;
 if(loaded.header!=original.header||loaded.strings!=original.strings||loaded.elements.size()!=original.elements.size())throw std::runtime_error("graph preservation");for(uint32_t i=0;i<loaded.elements.size();++i){const auto&o=original.elements[i];const auto&e=expected.elements[i];const auto&r=loaded.elements[i];if(o.type!=r.type||o.name!=r.name||o.id!=r.id||o.attributes.size()!=r.attributes.size())throw std::runtime_error("element preservation");for(size_t j=0;j<r.attributes.size();++j){const auto&a=o.attributes[j];const auto&b=r.attributes[j];if(a.name!=b.name||a.type!=b.type||a.values.size()!=b.values.size())throw std::runtime_error("attribute preservation");for(size_t k=0;k<b.values.size();++k){const auto&v=a.values[k];const auto&w=b.values[k];if(v.reference!=w.reference||v.text!=w.text||v.stringIndex!=w.stringIndex||w.wire!=e.attributes[j].values[k].wire)throw std::runtime_error("payload mismatch");if(v.wire!=w.wire){if(original.strings[b.name]!="orientation"||!changed.count({i,"orientation"}))throw std::runtime_error("unjournaled mutation");++changedValues;}}}}
 p.scene.cleanup({},[](auto&,bool){},[](auto&){});if(p.scene.size()||p.scene.attributes.size()||p.scene.references.nodes.allocationCount())throw std::runtime_error("teardown");std::cout<<"owned_ik_executions="<<result.executed<<" skipped="<<result.skipped<<" changed_values="<<changedValues<<" exact_expected_payload_preservation_reload_teardown=passed\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
